    tauv: float,
    taue: float,
    tauev: float,
    t0c: float,
    tzc: float,
    txc: float,
    dzi: float,
    dxi: float,
    dz2i: float,
    dx2i: float,
    vzero: float,
    vref: float,
    sgntz: float,
    sgntx: float
) -> float {
