) -> object {
    result = str;
    for i in caseTypes.lower() {
        if (i == "c") {
            result = result.replace(wordToReplace, replaceWithWord);
        } elif (i == "") {
            result = result.replace(wordToReplace.upper(), replaceWithWord.upper());
        } elif (i == "l") {
